import pickle
from pathlib import Path

import cmocean as cm

# import matplotlib.colors as mcolors
import matplotlib.dates as mdates
import matplotlib.pyplot as plt

# import pandas as pd  # not called, but pandas Dataframe are pickled
import numpy as np

import pinner2026_jpo_code
import pinner2026_jpo_code.plots

ONE_COLUMN_WIDTH = pinner2026_jpo_code.plots.ONE_COLUMN_WIDTH
TWO_COLUMN_WIDTH = pinner2026_jpo_code.plots.TWO_COLUMN_WIDTH

INTERIM_DATA_DIR: Path = pinner2026_jpo_code.DATA_DIR / "interim"
FIGURE_DIR: Path = pinner2026_jpo_code.FIGURE_DIR

# both files are generated by scripts/Vertical_energy_propagation_from_ADCP_data/ADCP_analysis.ipynb
with open(INTERIM_DATA_DIR / "NIW_filtered.pickle", "rb") as NIW_file:
    NIW_dict = pickle.load(NIW_file)
with open(INTERIM_DATA_DIR / "IT_filtered.pickle", "rb") as IT_file:
    IT_dict = pickle.load(IT_file)

# --- Config -------------------------------------------------------------

HALFRANGE = 0.05  # symmetric color limits (+/- m/s) for the raw-v snapshot panels

# 24-hour window shown in the narrow "raw v" snapshot panels.
# Edit these two dates to look at a different day.
SNAPSHOT_START = "2022-11-15"
SNAPSHOT_END = "2022-11-16"

# --- Figure / axes layout ------------------------------------------------
# 4 columns: [NIWs (wide), NIWs snapshot (narrow), NIWs+ITs (wide), NIWs+ITs snapshot (narrow)]
fig, axs = plt.subplots(
    ncols=4,
    nrows=2,
    sharey=True,
    figsize=(TWO_COLUMN_WIDTH, 4),
    layout="constrained",
    gridspec_kw={"width_ratios": [4, 1, 4, 1]},
)

# wide (original) axes and narrow (new snapshot) axes, kept as separate views
main_ax = axs[:, [0, 2]]  # column 0 = NIWs, column 1 = NIWs + ITs
snap_ax = axs[:, [1, 3]]  # same column meaning, narrow companion panels

main_ax[0, 0].set_title("NIWs")
main_ax[0, 1].set_title("NIWs + ITs")
# snap_ax[0, 0].set_title("24 h raw $v$", fontsize="small")
# snap_ax[0, 1].set_title("24 h raw $v$", fontsize="small")

im_main = None
im_snap = None

# NIW plotting
for i, (name, data) in enumerate(NIW_dict.items()):
    if name == "raw":
        continue
    if "CCW" not in name:
        continue

    v_complex = data.apply(np.imag)  # v (east) velocity, before rolling mean

    # daily rolling mean of the v component, for the wide panel
    data_mean = v_complex.abs().rolling("1D").mean()

    if "dn" in name:
        title_direction = "downwards"
    else:
        title_direction = "upwards"

    main_ax[i, 0].set_ylabel(title_direction)
    im_main = main_ax[i, 0].pcolormesh(
        data_mean.index,
        data_mean.columns,
        data_mean.to_numpy().T,
        cmap=cm.cm.speed,  # pyright: ignore[reportAttributeAccessIssue]
        vmax=0.08,
        vmin=0,
        rasterized=True,
    )

    # narrow panel: raw (pre-rolling-mean) signed v, 24h snapshot, as elapsed hours
    v_snapshot = v_complex.loc[SNAPSHOT_START:SNAPSHOT_END]
    elapsed_hours = (v_snapshot.index - np.datetime64(SNAPSHOT_START)).total_seconds() / 3600.0
    im_snap = snap_ax[i, 0].pcolormesh(
        elapsed_hours,
        v_snapshot.columns,
        v_snapshot.to_numpy().T,
        cmap=cm.cm.balance,  # pyright: ignore[reportAttributeAccessIssue]
        vmin=-HALFRANGE,
        vmax=HALFRANGE,
        rasterized=True,
    )

# IT plotting
for i, (name, data) in enumerate(IT_dict.items()):
    if name == "raw":
        continue
    if "CCW" not in name:
        continue

    v_complex = data.apply(np.imag)

    data_mean = v_complex.abs().rolling("1D").mean()

    if "dn" in name:
        title_direction = "downwards"
    else:
        title_direction = "upwards"

    assert main_ax[i, 0].get_ylabel() == title_direction

    im_main = main_ax[i, 1].pcolormesh(
        data_mean.index,
        data_mean.columns,
        data_mean.to_numpy().T,
        cmap=cm.cm.speed,  # type: ignore
        vmax=0.08,
        vmin=0,
        rasterized=True,
    )

    v_snapshot = v_complex.loc[SNAPSHOT_START:SNAPSHOT_END]
    elapsed_hours = (v_snapshot.index - np.datetime64(SNAPSHOT_START)).total_seconds() / 3600.0
    im_snap = snap_ax[i, 1].pcolormesh(
        elapsed_hours,
        v_snapshot.columns,
        v_snapshot.to_numpy().T,
        cmap=cm.cm.balance,  # type: ignore
        vmin=-HALFRANGE,
        vmax=HALFRANGE,
        rasterized=True,
    )

fig.supylabel("Meters above ground")

# wide panels: full record, date-formatted ticks
for axis in main_ax.flatten():
    axis.set_xlim(mdates.datestr2num("2022-11-15"), mdates.datestr2num("2022-12-24"))
    locator = mdates.AutoDateLocator(minticks=3, maxticks=8)
    formatter = mdates.ConciseDateFormatter(locator)
    axis.xaxis.set_major_locator(locator)
    axis.xaxis.set_major_formatter(formatter)

# narrow panels: 24h elapsed-time axis (timedelta from SNAPSHOT_START), in hours
for axis in snap_ax.flatten():
    axis.set_xlim(0, 24)
    axis.set_xticks(np.arange(6, 25, 12))
for axis in snap_ax[-1, :]:
    axis.set_xlabel(" hours")

# colorbar below the first two columns (NIWs: wide + narrow panels)
cbar_main = fig.colorbar(im_main, ax=axs[:, 0:2], location="bottom", shrink=0.8, extend="max")
cbar_main.set_label("daily |v| / (m s$^{-1}$)")

# colorbar below the second two columns (NIWs + ITs: wide + narrow panels)
cbar_snap = fig.colorbar(im_snap, ax=axs[:, 2:4], location="bottom", shrink=0.8, extend="both")
cbar_snap.set_label("v / (m s$^{-1}$)")

